79	      ...options,
80	      signal: controller.signal,
81	    });
82	    let data;
83	    try {
84	      data = await response.json();
85	    } catch {
86	      throw new Error(
87	        `The server returned an unreadable response (${response.status}). Check the server and try again.`,
88	      );
89	    }
90	    if (!response.ok) {
91	      const detail =
92	        typeof data.detail === "string"
93	          ? data.detail
94	          : `Request failed (${response.status}). Check the repository URL and try again.`;
95	      throw new Error(detail);
96	    }
97	    return data;
98	  } catch (error) {
99	    if (error.name === "AbortError")
100	      throw new Error(
101	        "The request timed out. Analysis may still finish on the server; check server logs before trying again.",
102	      );
103	    if (error instanceof TypeError)
104	      throw new Error(
105	        "Could not reach the server. Check your connection and try again.",
106	      );
107	    throw error;
108	  } finally {
109	    clearTimeout(timeout);
110	  }
111	}
