      const btn = document.getElementById('btn');
      const btnLabel = document.getElementById('btn-label');
      const orb = document.getElementById('orb');
      const statusEl = document.getElementById('status');
      const statusText = document.getElementById('status-text');
      let ws = null, player = null, live = false, finished = false;

      function setStatus(text, isError = false) {
        statusText.textContent = text;
        statusEl.className = 'interview-status' + (isError ? ' error' : '');
      }

      // The only thing this page learns about the session: a first name and whether it can start.
      async function checkLink() {
        try {
          const response = await fetch(`/sessions/${encodeURIComponent(sessionId)}/public`);
          if (!response.ok) throw new Error('This interview link is not valid.');
          const info = await response.json();
          document.getElementById('title').textContent = `Hi ${info.first_name}, ready when you are.`;
          if (info.state === 'done') {
            document.getElementById('intro').textContent =
              'This interview has already been completed. Thank you, the team will be in touch.';
            setStatus('Interview completed');
          } else if (info.state === 'not_ready') {
            setStatus('Your interview is still being prepared. Try again in a minute.');
          } else {
