          onEvent: (type, msg) => {
            if (type === 'interview_finished') {
              live = false;  // stop sending mic audio; let the goodbye play out
              const ENDINGS = {
                completed: 'Interview finished. Thank you, the team will be in touch.',
                time_limit: 'We have reached the time limit. Thank you, the team will be in touch.',
                stopped: 'Interview ended.',
              };
              // A finished interview cannot be taken again; one that was stopped early can.
              finished = msg.reason === 'completed' || msg.reason === 'time_limit';
              setStatus(ENDINGS[msg.reason] || 'Interview ended.');
            }
          },
          onError: (error) => setStatus(error.message, true),
        });

        try {
          await player.start();
        } catch (error) {
          setStatus('Microphone access denied', true);
          player = null;
          return;
        }

        const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
        ws = new WebSocket(`${protocol}//${location.host}/sessions/${sessionId}/interview`);
        ws.onopen = () => {
          ws.send(JSON.stringify({ type: 'start' }));
          live = true;
          orb.classList.add('live');
          btnLabel.textContent = 'End interview';
          setStatus('Interview in progress');
        };
        ws.onmessage = (event) => player && player.handleMessage(event.data);
        ws.onerror = () => setStatus('Connection error', true);
        ws.onclose = () => {
          if (!finished && !statusEl.classList.contains('error') && statusText.textContent === 'Interview in progress')
            setStatus('Disconnected');
          teardown();
        };
